    nums.sort((a, b) => a - b);
    const n = nums.length;
    const dp = new Array(n).fill(1);
    const parent = new Array(n).fill(-1);
    let max_idx = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (nums[i] % nums[j] === 0 && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
                parent[i] = j;
            }
        }
        if (dp[i] > dp[max_idx]) max_idx = i;
    }
    const res = [];
    let curr = max_idx;
    while (curr !== -1) {
        res.push(nums[curr]);
        curr = parent[curr];
    }
    return res.reverse();
